Date:   Mon Aug 20 15:54:43 2012 -0400

    When autocreating a display, check for the DataSource property that says
    we wanted to match times.  If this is true, then create a dataselection
    with the USETIMEDRIVER property set and pass that along.  This keeps the
    separation between the DataSource and DisplayControl.

diff --git a/src/ucar/unidata/idv/control/DisplayControlImpl.java b/src/ucar/unidata/idv/control/DisplayControlImpl.java
--- a/src/ucar/unidata/idv/control/DisplayControlImpl.java
+++ b/src/ucar/unidata/idv/control/DisplayControlImpl.java
@@ -1075,70 +1100,71 @@
 
         // set the sampling mode
         defaultSamplingMode = getObjectStore().get(PREF_SAMPLING_MODE,
                 DEFAULT_SAMPLING_MODE);
 
         //Check if we have been removed
         if (hasBeenRemoved) {
             return;
         }
 
         if (initialSettings != null) {
             try {
                 for (int i = 0; i < initialSettings.size(); i++) {
                     applyDisplaySetting(
                         (DisplaySetting) initialSettings.get(i));
                 }
                 initialSettings = null;
             } catch (Exception exc) {
                 logException("Initializing with settings", exc);
             }
         }
 
         // we do this here because time driver properties 
         // might be changed by the display settings.
         updateDataSelection(this.dataSelection);
 
 
         //Call the derived class init method.
         //        System.err.println("CALLING INIT " + mycnt);
 
 
         if ( !init(myDataChoices)) {
             displayControlFailed();
             if (getProperty("control.ignoreerrors", false)) {
                 addToControlContext();
             }
             return;
---
